  // ---------- File validation ----------
  function validateFile(file){
    var name = file.name || "";
    var ext = name.indexOf(".") > -1 ? name.split(".").pop().toLowerCase() : "";
    var rule = ALLOWED[ext];
    if (!rule) return {ok:false, error:"\"" + name + "\" is not allowed. Only JPG, JPEG, PNG, PDF, DOC and DOCX files can be uploaded."};
    var type = (file.type || "").toLowerCase();
    if (type && rule.mimes.indexOf(type) === -1) return {ok:false, error:"The actual format of \"" + name + "\" is not valid. Only genuine JPG, PNG, PDF or Word files are allowed."};
    if (file.size === 0) return {ok:false, error:"The file is empty."};
    if (file.size > MAX_SIZE) return {ok:false, error:"The file is too large (" + fmtSize(file.size) + "). Maximum 8 MB allowed."};
    return {ok:true, ext:ext, kind:rule.kind, mime:rule.mime};
  }

  function checkMagic(buf, kind, ext){
    var b = new Uint8Array(buf.slice(0, 8));
    if (ext === "png") return b[0]===0x89 && b[1]===0x50 && b[2]===0x4E && b[3]===0x47;
    if (kind === "image") return b[0]===0xFF && b[1]===0xD8 && b[2]===0xFF;
    if (kind === "pdf") return b[0]===0x25 && b[1]===0x50 && b[2]===0x44 && b[3]===0x46;
    if (ext === "docx") return b[0]===0x50 && b[1]===0x4B;
    if (ext === "doc") return b[0]===0xD0 && b[1]===0xCF && b[2]===0x11 && b[3]===0xE0;
    return false;
  }

  function toBase64(buf){
    var bytes = new Uint8Array(buf), bin = "", chunk = 0x8000;
    for (var i = 0; i < bytes.length; i += chunk) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
    return btoa(bin);
  }

  // ---------- Word text extraction (in the browser) ----------
  function inflateRaw(bytes){
    if (typeof DecompressionStream === "undefined") return Promise.reject(new Error("Old browser"));
    var stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("deflate-raw"));
    return new Response(stream).arrayBuffer().then(function(ab){ return new Uint8Array(ab); });
  }

  function docxText(buf){
    var u8 = new Uint8Array(buf), dv = new DataView(buf);
    var eocd = -1;
    for (var i = u8.length - 22; i >= Math.max(0, u8.length - 66000); i--){ if (dv.getUint32(i, true) === 0x06054b50){ eocd = i; break; } }
    if (eocd < 0) return Promise.reject(new Error("Broken docx"));
    var count = dv.getUint16(eocd + 10, true), p = dv.getUint32(eocd + 16, true);
    for (var n = 0; n < count; n++){
      if (dv.getUint32(p, true) !== 0x02014b50) break;
      var method = dv.getUint16(p + 10, true), csize = dv.getUint32(p + 20, true);
      var nlen = dv.getUint16(p + 28, true), xlen = dv.getUint16(p + 30, true), clen = dv.getUint16(p + 32, true);
      var loff = dv.getUint32(p + 42, true);
      var fname = new TextDecoder().decode(u8.subarray(p + 46, p + 46 + nlen));
      if (fname === "word/document.xml"){
        var start = loff + 30 + dv.getUint16(loff + 26, true) + dv.getUint16(loff + 28, true);
        var data = u8.subarray(start, start + csize);
        var prom = method === 0 ? Promise.resolve(data) : inflateRaw(data);
        return prom.then(function(x){
          var xml = new TextDecoder().decode(x);
          xml = xml.replace(/<w:tab\/>/g, "\t").replace(/<w:br[^>]*\/>/g, "\n").replace(/<\/w:p>/g, "\n").replace(/<[^>]+>/g, "");
          var ta = document.createElement("textarea"); ta.innerHTML = xml;
          return ta.value.replace(/\n{3,}/g, "\n\n").trim();
        });
      }
      p += 46 + nlen + xlen + clen;
    }
    return Promise.reject(new Error("No document text found"));
  }

  function docText(buf){
    // Legacy .doc file: best-effort text extraction
    var u8 = new Uint8Array(buf), out = [], run = "";
    for (var i = 0; i < u8.length - 1; i += 2){
      var code = u8[i] | (u8[i+1] << 8);
      if ((code >= 32 && code < 0xD800) || code === 10 || code === 13 || code === 9){ run += String.fromCharCode(code); }
      else { if (run.replace(/\s/g, "").length >= 4) out.push(run); run = ""; }
    }
    if (run.replace(/\s/g, "").length >= 4) out.push(run);
    var utf16 = out.filter(function(s){ return /[A-Za-z\u0600-\u06FF]{3,}/.test(s); }).join("\n");
    var latin = new TextDecoder("latin1").decode(u8).match(/[\x20-\x7E\r\n\t]{6,}/g) || [];
    var asc = latin.filter(function(s){ return /[A-Za-z]{3,}\s+[A-Za-z]{2,}/.test(s); }).join("\n");
    var t = (utf16.length > asc.length ? utf16 : asc).replace(/\r/g, "\n").replace(/\n{3,}/g, "\n\n").trim();
    return Promise.resolve(t);
  }

  function showFileError(msg){ var e = $("dg-ferr"); e.textContent = msg; e.classList.add("show"); }
  function clearFileError(){ $("dg-ferr").classList.remove("show"); }

  function handleFile(file){
    clearFileError();
    if (!file) return;
    var v = validateFile(file);
    if (!v.ok){ clearPending(); showFileError(v.error); return; }
    var reader = new FileReader();
    reader.onerror = function(){ showFileError("Could not read the file, please try again."); };
    reader.onload = function(){
      var buf = reader.result;
      if (!checkMagic(buf, v.kind, v.ext)){ clearPending(); showFileError("\"" + file.name + "\" does not look like a genuine " + v.ext.toUpperCase() + " file. Please upload a valid file."); return; }
      var p = {name: file.name, size: file.size, ext: v.ext, kind: v.kind, mimeType: v.mime};
      if (v.kind === "doc"){
        (v.ext === "docx" ? docxText(buf) : docText(buf)).then(function(t){
          if (!t){ showFileError("Could not extract text from this Word file. Save it as .docx or PDF and try again."); return; }
          p.text = t.slice(0, 60000); setPending(p);
        }).catch(function(){ showFileError("Could not extract text from this Word file. Save it as .docx or PDF and try again."); });
      } else {
        p.data = toBase64(buf);
        if (v.kind === "image") p.preview = "data:" + v.mime + ";base64," + p.data;
        setPending(p);
      }
    };
    reader.readAsArrayBuffer(file);
  }

  function iconFor(kind){ return kind === "pdf" ? '<span class="dg-ficon pdf">PDF</span>' : kind === "doc" ? '<span class="dg-ficon doc">DOC</span>' : '<span class="dg-ficon img">IMG</span>'; }

  function setPending(p){
    pending = p;
    $("dg-pthumb").innerHTML = p.preview ? '<img src="' + p.preview + '" alt="">' : iconFor(p.kind);
    $("dg-pinfo").querySelector(".n").textContent = p.name;
    $("dg-pinfo").querySelector(".s").textContent = fmtSize(p.size) + (p.kind === "doc" ? " - text ready" : "");
    $("dg-preview").classList.add("show");
    if (currentModel.type === "darkgptimg"){ currentModel = {type:"darkgpt"}; persistModel(); updatePill(); renderModelMenu(); }
    input.focus();
  }
  function clearPending(){ pending = null; fileInput.value = ""; $("dg-preview").classList.remove("show"); }

  // ---------- Markdown ----------
  function md(text){
    var blocks = [];
    text = String(text || "").replace(/```(\w*)\n?([\s\S]*?)```/g, function(m, lang, code){
      blocks.push({lang: lang || "code", code: code.replace(/\n$/, "")});
      return "\u0000" + (blocks.length - 1) + "\u0000";
    });
    var html = esc(text)
      .replace(/`([^`\n]+)`/g, '<code class="inl">$1</code>')
      .replace(/\*\*([^*]+)\*\*/g, "<b>$1</b>")
      .replace(/~~([^~]+)~~/g, "<del>$1</del>")
      .replace(/(^|[^*])\*([^*\n]+)\*/g, "$1<i>$2</i>")
      .replace(/\[([^\]]+)\]\((https?:[^)\s]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');
    var lines = html.split("\n"), out = [], list = null, quote = false, table = false;
    function closeAll(){
      if (list){ out.push("</"+list+">"); list = null; }
      if (quote){ out.push("</blockquote>"); quote = false; }
      if (table){ out.push("</tbody></table>"); table = false; }
    }
    function row(cells, tag){ return "<tr>" + cells.map(function(c){ return "<"+tag+">"+c+"</"+tag+">"; }).join("") + "</tr>"; }
    for (var i = 0; i < lines.length; i++){
      var l = lines[i], m;
      if (/^\s*\|.*\|\s*$/.test(l)){
        var cells = l.trim().replace(/^\||\|$/g, "").split("|").map(function(s){ return s.trim(); });
        var isSep = cells.length > 0 && cells.every(function(c){ return /^:?-{2,}:?$/.test(c); });
        if (isSep && table) continue; // header/body separator
        if (!table){ closeAll(); out.push('<table><thead>' + row(cells, "th") + '</thead><tbody>'); table = true; continue; }
        out.push(row(cells, "td")); continue;
      } else if (table){ out.push("</tbody></table>"); table = false; }
      if ((m = l.match(/^\s*&gt;\s?(.*)/))){
        if (list){ out.push("</"+list+">"); list = null; }
        if (!quote){ out.push("<blockquote>"); quote = true; }
        out.push("<p>"+m[1]+"</p>"); continue;
      } else if (quote){ out.push("</blockquote>"); quote = false; }
      if (/^\s*(-{3,}|\*{3,}|_{3,})\s*$/.test(l)){ closeAll(); out.push("<hr>"); continue; }
      if ((m = l.match(/^\s*[-*]\s+(.*)/))){
        if (list !== "ul"){ if (list) out.push("</"+list+">"); out.push("<ul>"); list = "ul"; }
        out.push("<li>"+m[1]+"</li>"); continue;
      }
      if ((m = l.match(/^\s*\d+[.)]\s+(.*)/))){
        if (list !== "ol"){ if (list) out.push("</"+list+">"); out.push("<ol>"); list = "ol"; }
        out.push("<li>"+m[1]+"</li>"); continue;
      }
      if (list){ out.push("</"+list+">"); list = null; }
      if ((m = l.match(/^(#{1,3})\s+(.*)/))) { out.push("<h"+m[1].length+">"+m[2]+"</h"+m[1].length+">"); continue; }
      if (l.trim() === "") continue;
      out.push("<p>"+l+"</p>");
    }
    closeAll();
    return out.join("").replace(/(?:<p>)?\u0000(\d+)\u0000(?:<\/p>)?/g, function(m, n){
      var b = blocks[+n];
      return '<div class="dg-code"><div class="dg-code-h"><span>'+esc(b.lang)+'</span><button data-code="'+encodeURIComponent(b.code)+'">Copy</button></div><pre><code>'+esc(b.code)+'</code></pre></div>';
    });
  }

  // ---------- Chats ----------
  function newChat(){
    chats = chats.filter(function(c){ return c.messages.length > 0; });
    current = {id: uid(), title: "New Chat", messages: []};
    chats.unshift(current); save(); render();
  }

  function matchesQuery(c){
    var q = $("dg-search").value.trim().toLowerCase();
    if (!q) return true;
    if ((c.title || "").toLowerCase().indexOf(q) > -1) return true;
    return (c.messages || []).some(function(m){ return (m.text || "").toLowerCase().indexOf(q) > -1; });
  }

  function renderHistory(){
    var h = $("dg-history"); h.innerHTML = "";
    var hasChats = chats.some(function(c){ return c.messages.length > 0; });
    $("dg-search").parentNode.style.display = hasChats ? "" : "none";
    var shown = chats.filter(matchesQuery).filter(function(c){ return c.messages.length > 0; });
    shown.sort(function(a, b){ return (b.pinned ? 1 : 0) - (a.pinned ? 1 : 0); });
    if (!shown.length){
      var n = document.createElement("div"); n.className = "dg-none";
      n.textContent = hasChats ? "No chats found" : "No chats yet";
      h.appendChild(n); return;
    }
    shown.forEach(function(c){
      var d = document.createElement("div");
      d.className = "dg-hist" + (current && c.id === current.id ? " active" : "");
      d.innerHTML = '<span class="t">' + (c.pinned ? '<span class="pintag">&#128204;</span>' : '') + esc(c.title) + '</span><span class="acts">' +
        '<button class="pn' + (c.pinned ? " on" : "") + '" title="' + (c.pinned ? "Unpin" : "Pin") + '">' + PIN_SVG + '</button>' +
        '<button class="rn" title="Rename">&#9998;</button><button class="del" title="Delete">&#10005;</button></span>';
      function renameInline(){
        var tEl = d.querySelector(".t");
        tEl.innerHTML = '<input class="dg-rename" value="' + esc(c.title) + '">';
        var inp = tEl.querySelector("input");
        inp.focus(); inp.select();
        var done = false;
        function commit(saveIt){
          if (done) return; done = true;
          var nn = inp.value.trim();
          if (saveIt && nn && nn !== c.title){ c.title = nn.slice(0, 60); save(); }
          renderHistory();
        }
        inp.onkeydown = function(ev){
          ev.stopPropagation();
          if (ev.key === "Enter") commit(true);
          else if (ev.key === "Escape") commit(false);
        };
        inp.onblur = function(){ commit(true); };
        inp.onclick = function(ev){ ev.stopPropagation(); };
      }
      d.querySelector(".rn").onclick = function(e){ e.stopPropagation(); renameInline(); };
      d.querySelector(".pn").onclick = function(e){ e.stopPropagation(); c.pinned = !c.pinned; save(); renderHistory(); };
      d.querySelector(".del").onclick = function(e){
        e.stopPropagation();
        chats = chats.filter(function(x){ return x.id !== c.id; });
        if (current && current.id === c.id) current = chats[0] || null;
        save(); if (!current) newChat(); else render();
      };
      d.ondblclick = function(e){ if (e.target.closest(".acts")) return; renameInline(); };
      d.onclick = function(e){
        if (e.target.closest(".acts")) return;
        current = c; render(); closeSidebar();
      };
      h.appendChild(d);
    });
  }

  function stripForSpeech(t){
    return String(t || "").replace(/```[\s\S]*?```/g, " (code block skipped) ")
      .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1").replace(/[#*_`>~|]/g, "").trim();
  }

  function msgHTML(m, isLastBot){
    if (m.callNote) return '<div style="text-align:center;margin-bottom:18px"><span class="dg-callnote">&#9742; ' + esc(m.text) + '</span></div>';
    var isUser = m.role === "user";
    var body = "";
    if (isUser && m.file){
      body += m.thumb ? '<img class="dg-uimg" src="'+m.thumb+'" alt="">' : '<div class="dg-fchip">'+iconFor(m.file.kind)+esc(m.file.name)+'</div>';
      body += m.text ? "\n" : "";
    }
    if (m.voice) body += '<span class="dg-callnote">&#127908; voice</span>\n';
    body += isUser ? esc(m.text) : md(m.text);
    if (m.image){
      body += '<img class="dg-img" src="'+m.image+'" alt="Generated image">' +
        '<div class="dg-actions"><a href="'+m.image+'" download="darkgpt-image.png">Download</a>' +
        (m.model ? '<span class="dg-mtag">'+esc(m.model)+'</span>' : '') +
        (m.ts ? '<span class="dg-time">'+fmtTime(m.ts)+'</span>' : '') + '</div>';
    } else if (!isUser){
      var acts = "";
      if (!m.err) acts += '<button data-copytext="'+encodeURIComponent(m.text||"")+'">Copy</button>';
      acts += '<button data-speak="'+encodeURIComponent(stripForSpeech(m.text))+'">Listen</button>';
      if (isLastBot) acts += m.err ? '<button data-retry="1">Retry</button>' : '<button data-regen="1">Regenerate</button>';
      if (m.model) acts += '<span class="dg-mtag">'+esc(m.model)+'</span>';
      if (m.ts) acts += '<span class="dg-time">'+fmtTime(m.ts)+'</span>';
      body += '<div class="dg-actions">'+acts+'</div>';
    }
    return '<div class="dg-msg '+(isUser?"user":"bot")+(m.err?" err":"")+'"><div class="dg-av'+(!isUser && m.mprov ? " haspv" : "")+'">'+(isUser ? userInitial() : (m.mprov ? badge(m.mprov) : '<img src="'+LOGO+'" alt="">'))+'</div><div class="dg-body">'+body+'</div></div>';
  }

  function render(opts){
    renderHistory();
    var btm = $("dg-bottom");
    if (btm && btm.parentElement !== $("dg-main")) $("dg-main").appendChild(btm);
    if (!current.messages.length){
      msgsEl.innerHTML = '<div class="dg-welcome"><h2 class="dg-wtitle">Where should we begin?</h2></div>';
      chatEl.classList.add("welcome");
      msgsEl.querySelector(".dg-welcome").appendChild(btm);
    } else {
      chatEl.classList.remove("welcome");
      var lastBot = -1;
      current.messages.forEach(function(m, i){ if (m.role === "bot") lastBot = i; });
      msgsEl.innerHTML = current.messages.map(function(m, i){ return msgHTML(m, i === lastBot); }).join("");
    }
    if (opts && opts.force) atBottom = true;
    if (atBottom) chatEl.scrollTop = chatEl.scrollHeight;
    scrollBtn.classList.toggle("show", !atBottom);
  }

