  // ---------- API keys modal ----------
  function renderApiList(){
    var box = $("dg-apilist"); box.innerHTML = "";
    Object.keys(PROVIDERS).forEach(function(pid){
      var p = PROVIDERS[pid], conn = providerConnected(pid);
      var card = document.createElement("div");
      card.className = "dg-apicard" + (conn ? " conn" : "") + (apiExp === pid ? " exp" : "");
      card.innerHTML =
        '<div class="dg-apihead">' + badge(pid) +
        '<div class="n"><b>' + esc(p.name) + '</b><small>' + esc(p.host) + '</small></div>' +
        '<span class="st' + (conn ? " ok" : "") + '">' + (conn ? "Connected" : "Not connected") + '</span></div>' +
        '<div class="dg-apibody">' +
        '<input class="dg-in dg-key" type="password" placeholder="Paste your API key here..." autocomplete="off" spellcheck="false">' +
        '<input class="dg-in dg-base" type="text" placeholder="Base URL (optional) - default: ' + p.host + '" autocomplete="off" spellcheck="false">' +
        '<div class="dg-apirow">' +
        '<button class="dg-btn dg-primary dg-test">' + (conn ? "Re-test & refresh models" : "Test & Connect") + '</button>' +
        (conn ? '<button class="dg-btn dg-dis">Disconnect</button><span class="dg-apiinfo">' + apiModels[pid].length + ' models loaded</span>' : '') +
        '</div><div class="dg-apierr"></div></div>';
      var input = card.querySelector(".dg-key");
      var baseInp = card.querySelector(".dg-base");
      if (keys[pid]) input.value = keys[pid];
      if (bases[pid]) baseInp.value = bases[pid];
      card.querySelector(".dg-apihead").onclick = function(){ apiExp = (apiExp === pid ? null : pid); renderApiList(); };
      var errEl = card.querySelector(".dg-apierr"), testBtn = card.querySelector(".dg-test");
      testBtn.onclick = function(){
        var key = input.value.trim();
        var bv = baseInp.value.trim();
        tempBase[pid] = bv;
        errEl.classList.remove("show");
        if (!key){ errEl.textContent = "Paste your API key first."; errEl.classList.add("show"); return; }
        testBtn.disabled = true;
        var old = testBtn.textContent; testBtn.textContent = "Testing...";
        fetchModels(pid, key).then(function(list){
          if (!list.length) throw new Error("No chat models found for this key.");
          keys[pid] = key; apiModels[pid] = list;
          if (bv) bases[pid] = bv; else delete bases[pid];
          saveApiState();
          if (currentModel.type === "provider" && currentModel.provider === pid && list.indexOf(currentModel.id) === -1) currentModel = {type:"darkgpt"};
          persistModel(); updatePill(); renderModelMenu(); updateApiBtn(); renderApiList();
          toast(p.name + " connected - " + list.length + " models loaded");
        }).catch(function(err){
          var msg = (err && err.message === "Failed to fetch")
            ? "Could not reach " + p.name + " from the browser (network or CORS blocked)."
            : ((err && err.message) || "Test failed.");
          errEl.textContent = msg; errEl.classList.add("show");
        }).finally(function(){ testBtn.disabled = false; testBtn.textContent = old; });
      };
      var dis = card.querySelector(".dg-dis");
      if (dis) dis.onclick = function(){
        delete keys[pid]; delete apiModels[pid]; delete bases[pid]; saveApiState();
        if (currentModel.type === "provider" && currentModel.provider === pid){ currentModel = {type:"darkgpt"}; persistModel(); }
        updatePill(); renderModelMenu(); updateApiBtn(); renderApiList();
        toast(p.name + " disconnected");
      };
      box.appendChild(card);
    });
  }
